# Reference values generated with PyTorch 2.11.0+cu128 on CPU.
# Exercise the same forward/gradient assertions in native Zipp and actual WASM.
import torch
import torch.nn.functional as F

# Case 0: batches, rectangular kernels, groups, stride/dilation and unbatched input.
dtype = torch.float64
x = torch.tensor([[[[-1.0, -0.875, -0.75, -0.625], [-0.5, -0.375, -0.25, -0.125], [0.0, 0.125, 0.25, 0.375]]]], dtype=dtype, requires_grad=True)
w = torch.tensor([[[[-0.5, -0.4375], [-0.375, -0.3125]]]], dtype=dtype, requires_grad=True)
b = torch.tensor([0.0], dtype=dtype, requires_grad=True)
y = F.conv2d(x, w, b, stride=(1, 1), padding=(0, 0), dilation=(1, 1), groups=1)
g = torch.tensor([[[[0.25, 0.35, 0.45], [0.55, 0.65, 0.75]]]], dtype=dtype)
(y * g).sum().backward()
assert torch.allclose(y, torch.tensor([[[[1.1875, 0.984375, 0.78125], [0.375, 0.171875, -0.03125]]]], dtype=dtype), rtol=0.00002, atol=0.00002), "case 0: y"
assert torch.allclose(x.grad, torch.tensor([[[[-0.125, -0.284375, -0.378125, -0.196875], [-0.36875, -0.775, -0.9375, -0.46875], [-0.20625000000000002, -0.415625, -0.484375, -0.234375]]]], dtype=dtype), rtol=0.00002, atol=0.00002), "case 0: x.grad"
assert torch.allclose(w.grad, torch.tensor([[[[-1.6, -1.225], [-0.09999999999999998, 0.275]]]], dtype=dtype), rtol=0.00002, atol=0.00002), "case 0: w.grad"
assert torch.allclose(b.grad, torch.tensor([3.0], dtype=dtype), rtol=0.00002, atol=0.00002), "case 0: b.grad"
print("conv2d case 0 passed")

