model = torch.nn.Conv2d(1, 1, 1, dtype=torch.float64)
with torch.no_grad():
    model.weight.fill_(0.5)
    model.bias.zero_()
x = torch.tensor([[[[1.,2.],[3.,4.]]]], dtype=torch.float64)
optimizer = torch.optim.SGD(model.parameters(), lr=0.01)
before = (model(x) ** 2).sum().item()
optimizer.zero_grad()
(model(x) ** 2).sum().backward()
optimizer.step()
assert (model(x) ** 2).sum().item() < before
assert sorted(model.state_dict().keys()) == ['bias', 'weight']
print('conv2d optimizer passed')
